def compute(vars):
    comparison_year_value = vars["Comparison Year Value"]
    base_year_value = vars["Base Year Value"]
    multiplier = vars["100"]

    if base_year_value == 0:
        return None

    difference = comparison_year_value - base_year_value
    percentage_change = difference / base_year_value * multiplier

    return {
        "value": percentage_change,
        "trace": {
            "Comparison Year Value": comparison_year_value,
            "Base Year Value": base_year_value,
            "100": multiplier,
            "Difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
